import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.mqZn2l2k.js";const c=JSON.parse('{"title":"附录 C 横向对比：n8n / Dify / LangGraph","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/c-comparison.md","filePath":"appendix/c-comparison.md","lastUpdated":1791458539000}'),n={name:"appendix/c-comparison.md"};function o(i,t,h,s,g,l){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="附录-c-横向对比-n8n-dify-langgraph" tabindex="-1">附录 C 横向对比：n8n / Dify / LangGraph <a class="header-anchor" href="#附录-c-横向对比-n8n-dify-langgraph" aria-label="Permalink to &quot;附录 C 横向对比：n8n / Dify / LangGraph&quot;">​</a></h1><blockquote><p>目的：把本书学到的概念放进更大的版图。各项目都在快速迭代，以下是<strong>架构层面</strong>的比较，具体功能以各自官方文档为准。</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>n8n</th><th>Dify</th><th>LangGraph</th></tr></thead><tbody><tr><td>形态</td><td>开源工作流自动化平台</td><td>开源 LLM 应用平台（可视化 + API）</td><td>开源<strong>代码库</strong>（Python / JS）</td></tr><tr><td>主要用户</td><td>运营、自动化工程师、开发者</td><td>产品、业务、开发者</td><td>开发者</td></tr><tr><td>编排方式</td><td>画布 DAG，数据沿边传递</td><td>画布 DAG + 容器节点，共享变量池</td><td>用代码定义状态图（<strong>允许有环</strong>）</td></tr><tr><td>LLM 原生程度</td><td>中：AI 节点是几百种节点中的一类</td><td>高：模型、提示词、RAG、Agent 都是一等公民</td><td>高</td></tr><tr><td>节点生态</td><td>极广：500+ 集成（SaaS、数据库、文件…）</td><td>以 LLM 相关为主</td><td>靠 LangChain 生态</td></tr></tbody></table><p>一句话概括三者的性格：<strong>n8n 是“什么都能连的自动化平台，顺手把 AI 做成了节点”</strong>；Dify 是“专门为 LLM 应用设计的平台”；LangGraph 是“给开发者写 Agent 的库”。</p><h2 id="引擎模型" tabindex="-1">引擎模型 <a class="header-anchor" href="#引擎模型" aria-label="Permalink to &quot;引擎模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>n8n</th><th>Dify（graphon）</th><th>LangGraph</th></tr></thead><tbody><tr><td>图</td><td>DAG，数据沿边以 <strong>items 数组</strong> 传递</td><td>DAG（循环用容器节点实现）</td><td>有向图，<strong>可以有环</strong>；节点通过共享 State 通信</td></tr><tr><td>数据传递</td><td>沿边传递：上游输出即下游输入；跨节点引用用 <code>$(&#39;节点名&#39;)</code> 表达式</td><td>共享变量池 + selector</td><td>共享 State + reducer（定义更新怎样合并）</td></tr><tr><td>一个节点处理什么</td><td>一个 <strong>items 数组</strong>（天然支持“对每条数据做同样的事”）</td><td>一次调用</td><td>一次状态转换</td></tr><tr><td>分支</td><td>IF / Switch 节点</td><td>分支节点 + 边状态 + 跳过传播</td><td>条件边函数返回下一个节点</td></tr><tr><td>暂停 / 恢复</td><td>Wait 节点 + 执行数据序列化 + WaitTracker</td><td>人工输入节点 + 运行时状态序列化</td><td>Checkpointer 每步保存 State，<code>interrupt()</code> 支持人在回路，可“时间旅行”</td></tr><tr><td>执行顺序</td><td>v1：深度优先（执行栈 unshift）</td><td>就绪即执行</td><td>superstep（Pregel / BSP）</td></tr></tbody></table><p>几点值得注意：</p><ul><li><strong>n8n 的“items 数组”是它最鲜明的特征</strong>。每个节点天生对一个数组逐条处理，这对 ETL、批量操作特别顺手——“把这 100 行都发一遍邮件”不用写循环。代价是“引用三步之前某一条数据”要靠表达式，没有 Dify 变量池那么直接。</li><li><strong>LangGraph 允许有环</strong>，所以 Agent 循环（模型 ⇄ 工具）可以直接画成图里的环。n8n 和 Dify 都把 Agent 封装成一个节点，外层保持 DAG。这是<strong>可控性与表达力的不同取舍</strong>：DAG 好懂、好可视化，环更灵活但更难画清楚。</li><li><strong>三者的“暂停/恢复”深度不同</strong>。LangGraph 每个 superstep 都存 State，所以回放、时间旅行天然支持；n8n 和 Dify 只在需要暂停时才序列化。本书第 7、24 章实现的正是 n8n 这种“按需序列化 + 栈恢复”。</li></ul><h2 id="ai-agent-的实现方式" tabindex="-1">AI Agent 的实现方式 <a class="header-anchor" href="#ai-agent-的实现方式" aria-label="Permalink to &quot;AI Agent 的实现方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>n8n</th><th>Dify</th><th>LangGraph</th></tr></thead><tbody><tr><td>Agent 形态</td><td>一个 Cluster Node：AI Agent + 模型/记忆/工具子节点</td><td>一个 Agent 节点或 Agent 应用</td><td>用图直接表达（<code>create_react_agent</code> 或自定义图）</td></tr><tr><td>工具执行</td><td><strong>引擎</strong>执行工具节点（EngineRequest/Response，第 19 章）</td><td>Agent 节点内部调用</td><td>ToolNode，图里的一个节点</td></tr><tr><td>工具来源</td><td>专用工具节点、任意节点合成工具、子工作流、MCP</td><td>内置工具、自定义工具、MCP</td><td><code>@tool</code> 装饰的函数、LangChain 工具、MCP 适配器</td></tr><tr><td>把 Agent 当工具</td><td>AI Agent Tool（嵌套 EngineRequest，第 23 章）</td><td>Agent 作为工具</td><td>子图作为工具</td></tr><tr><td>结构化输出</td><td><code>format_final_json_response</code> 工具 + Output Parser</td><td>结构化输出功能</td><td><code>with_structured_output</code> / 工具</td></tr></tbody></table><p>n8n 把“工具执行交给引擎”这一步做得很有特色（第 19 章）：Agent 只是返回“我要调这些工具”，由引擎像执行普通节点一样执行它们，于是工具的运行记录、重试、错误处理全都复用了引擎已有的机制。本书第 19、20、23 章的大部分篇幅就在讲这件事。</p><h2 id="和本书概念的对应" tabindex="-1">和本书概念的对应 <a class="header-anchor" href="#和本书概念的对应" aria-label="Permalink to &quot;和本书概念的对应&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本书概念（n8n）</th><th>Dify</th><th>LangGraph</th></tr></thead><tbody><tr><td>items 沿边传递</td><td>变量池 VariablePool</td><td>共享 State</td></tr><tr><td>节点就绪 = 上游执行完</td><td>边状态</td><td>superstep</td></tr><tr><td>生命周期钩子</td><td>GraphEngineLayer</td><td>callbacks / checkpointer</td></tr><tr><td>EngineRequest（引擎跑工具）</td><td>Agent 节点内部</td><td>ToolNode</td></tr><tr><td>Cluster Node 子节点</td><td>容器节点</td><td>子图</td></tr><tr><td>Wait + WaitTracker</td><td>人工输入节点 + 序列化</td><td>Checkpointer + interrupt</td></tr><tr><td>队列模式 + worker</td><td>—</td><td>LangGraph Platform</td></tr><tr><td>发布为 Webhook / 开放 API</td><td>Service API</td><td>LangGraph Server</td></tr></tbody></table><h2 id="该选哪个" tabindex="-1">该选哪个？ <a class="header-anchor" href="#该选哪个" aria-label="Permalink to &quot;该选哪个？&quot;">​</a></h2><p>不是“哪个更好”，而是“哪个更贴你的问题”：</p><ul><li><strong>要把几十个 SaaS、数据库、文件系统串起来，顺带加点 AI</strong>：n8n。它的节点生态和“items 数组”模型就是为这个生的。</li><li><strong>要做一个以 LLM 为核心的产品（知识库问答、AI 客服），要开箱即用的 RAG 和提示词管理</strong>：Dify。</li><li><strong>要完全掌控 Agent 的每一步、要环、要时间旅行、能接受写代码</strong>：LangGraph。</li></ul><p>学完本书你会发现，这些平台共享同一批底层概念——图、节点、执行状态、工具、暂停恢复。换一个平台，换的只是这些概念的<strong>包装方式</strong>。这也是本书从零实现 mini-n8n 的意义：看清包装之下的东西，换什么平台都不怕。</p>',18)])])}const u=d(n,[["render",o]]);export{c as __pageData,u as default};
